namespace TacitMemory.Core.Skills;

/// <summary>
/// The shape the two memory commands share: a skill only the user can run. <c>disable-model-invocation</c> keeps the
/// model from invoking it and keeps it out of the skill list a session starts with; the user runs it by name, and any
/// text sent with it reaches the agent alongside the body.
/// </summary>
internal static class CommandSkill
{
    private const string Generated =
        "<!-- Generated by TacitMemory from its built-in text; changes made here are overwritten. -->";

    /// <summary>The sentence both commands carry about the text the user sends with them.</summary>
    public const string UserText =
        "Any text the user sent with this command is the focus of this run or an extra requirement; follow it.";

    /// <param name="description">One sentence for the client's command completion; a client may show only about the first 100 characters.</param>
    public static string Compose(string name, string description, string body) =>
        $"---\nname: {name}\ndescription: \"{description}\"\ndisable-model-invocation: true\n---\n\n{Generated}\n\n{body.ReplaceLineEndings("\n")}\n";
}
